// GENERATED by operator_voice.dashboard.generate — DO NOT hand-edit.
// Render-only Operator Voice status dashboard (build plan v4 §13 M4).
//
// Refresh against your live LOCAL profile (read-only — never mutates OVT state):
//     python -m operator_voice.dashboard.generate --out "<canvas path>"
// Re-emit the committed sample artifact:
//     python -m operator_voice.dashboard.generate --sample --out dashboard/operator-voice-status.canvas.tsx
//
// This canvas imports ONLY from "cursor/canvas", embeds a redacted content-free snapshot inline,
// and makes NO network call. Its only host action is a "Refresh" button that opens a new agent
// chat (newComposerChat) asking to re-run the read-only generator — it dispatches NO OVT operation
// and holds NO persistent canvas state (no useCanvasState), so it is structurally READ-ONLY and
// cannot change any OVT state. It never contains fact values, raw text, or an EXTERNAL subject's
// name.

import {
  Button,
  Callout,
  Card,
  CardBody,
  CardHeader,
  Divider,
  Grid,
  H1,
  H2,
  Pill,
  Row,
  Stack,
  Stat,
  Table,
  Text,
  useCanvasAction,
  useHostTheme,
} from "cursor/canvas";

const SNAPSHOT = {
  "facts": {
    "by_state": {
      "CONFIRMED": 3,
      "CORRECTED": 1,
      "SUPPORTED": 6
    },
    "total": 10
  },
  "gateway": {
    "external_egress_denials": 1,
    "recent_calls": [
      {
        "data_class": "external",
        "outcome": "DENIED_EXTERNAL_EGRESS",
        "purpose": "external_insight_summary"
      }
    ]
  },
  "generated_at": 0,
  "reviews": {
    "open_count": 1
  },
  "runtime": {
    "backend_active": false,
    "backend_mode": "LOCAL_ONLY",
    "external_egress_enabled": false,
    "model": null,
    "off": false,
    "operator_egress_enabled": false,
    "provider": null
  },
  "schema": "operator-voice-dashboard/v1",
  "subjects": {
    "external_alias_count": 1,
    "external_count": 1,
    "items": [
      {
        "active": true,
        "enrolled": true,
        "fact_count": 7,
        "generation_permission": true,
        "kind": "OPERATOR",
        "label": "me",
        "subject_id": "subj_sample_operator"
      },
      {
        "active": true,
        "enrolled": true,
        "fact_count": 3,
        "generation_permission": false,
        "kind": "EXTERNAL",
        "label": "EXTERNAL subject",
        "subject_id": "subj_sample_external"
      }
    ],
    "operator_count": 1
  },
  "sync": {
    "conflict_count": 0,
    "local_generation_id": null,
    "publish_status": "NOT_CONFIGURED",
    "remote_generation_id": null
  }
} as const;

type Snapshot = typeof SNAPSHOT;

function stateTone(state: string): "success" | "info" | "warning" | "neutral" {
  if (state === "CORRECTED" || state === "CONFIRMED") return "success";
  if (state === "SUPPORTED") return "info";
  if (state === "DEPRECATED") return "warning";
  return "neutral";
}

export default function OperatorVoiceStatusDashboard() {
  const theme = useHostTheme();
  const dispatch = useCanvasAction();
  const s: Snapshot = SNAPSHOT;
  const rt = s.runtime;
  const factStates = Object.entries(s.facts.by_state);
  // Refresh control. This opens a NEW agent chat (host navigation) asking to re-run the read-only
  // generator — it dispatches ONLY "newComposerChat" and can never invoke an OVT operation, so the
  // dashboard stays render-only and cannot mutate OVT state.
  const refresh = () =>
    dispatch({
      type: "newComposerChat",
      userPrompt:
        "Refresh this Operator Voice dashboard from my live local profile (read-only): run " +
        "`python -m operator_voice.dashboard.generate --out <path to this .canvas.tsx>`.",
    });
  return (
    <Stack gap={16} style={{ padding: 20, color: theme.text.primary }}>
      <Row justify="space-between" align="center">
        <Stack gap={4}>
          <H1>Operator Voice — Status</H1>
          <Text tone="secondary">
            Read-only snapshot from the `ovt://status/dashboard` source (operator-voice `dashboard.data`).
          </Text>
        </Stack>
        <Button onClick={refresh}>Refresh</Button>
      </Row>

      <Callout
        tone={rt.external_egress_enabled ? "warning" : "success"}
        title="Privacy posture"
      >
        <Text>
          Storage is <Text weight="semibold">{rt.backend_mode}</Text>
          {rt.off ? " · the toolkit is OFF (collection and egress paused)" : ""}. Operator model
          egress is{" "}
          <Text weight="semibold">{rt.operator_egress_enabled ? "enabled" : "disabled"}</Text>, and
          EXTERNAL-subject egress (a separate switch) is{" "}
          <Text weight="semibold">
            {rt.external_egress_enabled ? "ENABLED" : "disabled (default)"}
          </Text>
          .
        </Text>
      </Callout>

      <Grid columns={4} gap={12}>
        <Stat value={s.subjects.operator_count} label="Operator subjects" />
        <Stat value={s.subjects.external_count} label="External subjects" />
        <Stat value={s.facts.total} label="Profile facts" />
        <Stat
          value={s.reviews.open_count}
          label="Open reviews"
          tone={s.reviews.open_count > 0 ? "warning" : undefined}
        />
      </Grid>

      {factStates.length > 0 && (
        <Stack gap={8}>
          <H2>Facts by state</H2>
          <Table
            headers={["State", "Count"]}
            columnAlign={["left", "right"]}
            rows={factStates.map(([state, count]) => [state, String(count)])}
            rowTone={factStates.map(([state]) => stateTone(state))}
          />
        </Stack>
      )}

      {s.subjects.items.length > 0 && (
        <Stack gap={8}>
          <H2>Subjects</H2>
          <Table
            headers={["Subject", "Kind", "Facts", "Enrolled", "Generation context"]}
            columnAlign={["left", "left", "right", "left", "left"]}
            rows={s.subjects.items.map((it) => [
              it.label,
              it.kind,
              String(it.fact_count),
              it.enrolled ? "yes" : "no",
              it.generation_permission ? "allowed" : "never (external)",
            ])}
          />
        </Stack>
      )}

      <Grid columns={2} gap={16} align="start">
        <Card>
          <CardHeader trailing={<Pill active>{s.sync.publish_status}</Pill>}>
            Backend sync
          </CardHeader>
          <CardBody>
            <Stack gap={6}>
              <Row justify="space-between">
                <Text tone="secondary">Local generation</Text>
                <Text>{s.sync.local_generation_id ?? "—"}</Text>
              </Row>
              <Row justify="space-between">
                <Text tone="secondary">Remote generation</Text>
                <Text>{s.sync.remote_generation_id ?? "—"}</Text>
              </Row>
              <Divider />
              <Row justify="space-between">
                <Text tone="secondary">Unresolved conflicts</Text>
                <Text weight="semibold">{s.sync.conflict_count}</Text>
              </Row>
            </Stack>
          </CardBody>
        </Card>

        <Card>
          <CardHeader trailing={<Pill>{s.gateway.external_egress_denials} EXTERNAL denied</Pill>}>
            Model egress ledger
          </CardHeader>
          <CardBody>
            {s.gateway.recent_calls.length > 0 ? (
              <Table
                headers={["Purpose", "Class", "Outcome"]}
                rows={s.gateway.recent_calls.map((c) => [c.purpose, c.data_class, c.outcome])}
              />
            ) : (
              <Text tone="secondary">
                No model calls recorded — the deterministic kernel needs no model.
              </Text>
            )}
          </CardBody>
        </Card>
      </Grid>
    </Stack>
  );
}
